#!/usr/bin/env python3
"""regen.py: generated files are rebuilt by their generator, never typed by the Coder.

A run used to have the Coder re-type files like docs/i18n/uk-review.md (94 KB,
"Generated by `npm run i18n:review` ... Do not edit by hand"): tens of thousands of
output tokens for a file a script produces in a second, and a Verify failure
whenever the hand-made copy drifted from the script's output.

Usage:
  regen.py <repo> <run_id> detect   which of the Coder's MODIFY files are generated;
                                     writes runs/<run_id>/generated.json (seed-code.py
                                     calls this before every Coder pass)
  regen.py <repo> <run_id> run      after the orchestrator copies code/ into <repo>:
                                     run each generator in <repo>, copy the results back
                                     into runs/<run_id>/code/ so both stay identical

Which files are generated (read from the run's ORIGINAL branch, so a run can't change
what gets executed):
  1. "generated" in {REPO}/.claude/verify.json: [{"path": "...", "command": "..."}].
     Set it to [] or null to turn detection off for a repo.
  2. Otherwise, the file's own header: within its first 10 lines, both
     "Generated by `<command>`" and "do not edit". Only commands starting with
     npm/pnpm/yarn/npx/node/python/python3/bash/make are accepted from a header.
Only Coder-owned MODIFY files (contract.json) are considered.

Exit: detect 0 (3 on setup error); run always 0 (prints what it did; a failed
generator is reported, and Verify catches a stale file), 3 on usage errors.
"""
import json
import os
import re
import shutil
import subprocess
import sys

ORCH_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
HEADER_CMD = re.compile(r"[Gg]enerated by\s+`([^`\n]+)`")
DO_NOT_EDIT = re.compile(r"do not edit", re.I)
SAFE_CMD = re.compile(r"^(npm|pnpm|yarn|npx|node|python3?|bash|make)\s")


def read_state(run_dir):
    state = {}
    path = os.path.join(run_dir, "state.md")
    if os.path.exists(path):
        for line in open(path):
            if ":" in line:
                k, v = line.split(":", 1)
                state.setdefault(k.strip(), v.strip())
    return state


def git_show(repo, ref, path):
    r = subprocess.run(["git", "-C", repo, "show", "{}:{}".format(ref, path)],
                       stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    return r.stdout.decode("utf-8", "replace") if r.returncode == 0 else None


def coder_modify_files(run_dir):
    path = os.path.join(run_dir, "contract.json")
    if not os.path.isfile(path):
        return []
    data = json.load(open(path))
    return [e["path"] for e in data.get("files", [])
            if isinstance(e, dict) and e.get("action") == "modify" and e.get("owner") == "coder" and e.get("path")]


def detect(repo, run_id):
    run_dir = os.path.join(ORCH_ROOT, "runs", run_id)
    original = read_state(run_dir).get("original_branch") or "main"
    modify = coder_modify_files(run_dir)
    found = []

    raw = git_show(repo, original, ".claude/verify.json")
    cfg = None
    if raw and raw.strip().startswith("{"):
        try:
            cfg = json.loads(raw)
        except ValueError:
            cfg = None
    if isinstance(cfg, dict) and "generated" in cfg:
        for e in cfg.get("generated") or []:
            if isinstance(e, dict) and e.get("path") in modify and e.get("command"):
                found.append({"path": e["path"], "command": e["command"], "source": "verify.json"})
        return found, original

    for rel in modify:
        text = git_show(repo, original, rel)
        if not text:
            continue
        head = "\n".join(text.splitlines()[:10])
        m = HEADER_CMD.search(head)
        if m and DO_NOT_EDIT.search(head) and SAFE_CMD.match(m.group(1).strip() + " "):
            found.append({"path": rel, "command": m.group(1).strip(), "source": "file header"})
    return found, original


def cmd_detect(repo, run_id):
    run_dir = os.path.join(ORCH_ROOT, "runs", run_id)
    if not os.path.isdir(run_dir):
        print("ERROR: runs/{}/ not found".format(run_id), file=sys.stderr)
        return 3
    found, original = detect(repo, run_id)
    with open(os.path.join(run_dir, "generated.json"), "w") as f:
        json.dump({"original_branch": original, "files": found}, f, indent=2)
        f.write("\n")
    if found:
        print("regen: {} generated file(s), left to their generator: {}".format(
            len(found), ", ".join("{} (`{}`)".format(e["path"], e["command"]) for e in found)))
    else:
        print("regen: no generated files among the Coder's MODIFY files")
    return 0


def git_status(repo):
    r = subprocess.run(["git", "-C", repo, "status", "--porcelain"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    return set(r.stdout.decode("utf-8", "replace").splitlines())


def cmd_run(repo, run_id):
    run_dir = os.path.join(ORCH_ROOT, "runs", run_id)
    path = os.path.join(run_dir, "generated.json")
    if not os.path.isfile(path):
        cmd_detect(repo, run_id)
    files = json.load(open(path)).get("files") or []
    if not files:
        print("regen: nothing to regenerate")
        return 0

    by_cmd = {}
    for e in files:
        by_cmd.setdefault(e["command"], []).append(e["path"])
    before = git_status(repo)
    for cmd, paths in by_cmd.items():
        try:
            r = subprocess.run(["bash", "-c", cmd], cwd=repo, stdout=subprocess.PIPE,
                               stderr=subprocess.STDOUT, timeout=300)
            rc, out = r.returncode, r.stdout.decode("utf-8", "replace")
        except subprocess.TimeoutExpired:
            rc, out = "timeout", ""
        if rc != 0:
            print("regen: WARNING: `{}` exited {}; {} left as the Coder's copy (Verify will flag it if stale). "
                  "Last output:".format(cmd, rc, ", ".join(paths)))
            print("\n".join(out.strip().splitlines()[-15:]))
            continue
        for rel in paths:
            src, dst = os.path.join(repo, rel), os.path.join(run_dir, "code", rel)
            if not os.path.isfile(src):
                print("regen: WARNING: `{}` did not produce {}".format(cmd, rel))
                continue
            changed = not os.path.isfile(dst) or open(src, "rb").read() != open(dst, "rb").read()
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copyfile(src, dst)
            print("regen: `{}` -> {} ({})".format(cmd, rel, "updated" if changed else "unchanged"))

    expected = {p for ps in by_cmd.values() for p in ps}
    extra = sorted(l for l in git_status(repo) - before if l[3:] not in expected)
    if extra:
        print("regen: WARNING: the generator also changed files outside the generated list; review before committing:")
        print("\n".join("  " + l for l in extra))
    return 0


def main():
    if len(sys.argv) != 4 or sys.argv[3] not in ("detect", "run"):
        print(__doc__)
        return 3
    repo, run_id, mode = os.path.abspath(sys.argv[1]), sys.argv[2], sys.argv[3]
    return cmd_detect(repo, run_id) if mode == "detect" else cmd_run(repo, run_id)


if __name__ == "__main__":
    sys.exit(main())
